/* helper: pure, formats into the caller's buffer, owns no I/O */
static int fmt_money(char *out, size_t n, long cents, const char *cur)
{ return snprintf(out, n, "%s %.2f", cur, (double)cents / 100.0); }
/* the view owns the stream; the helper never prints */
static void account_row(FILE *out, const account_t *a)
{
    char buf[32];
    if (fmt_money(buf, sizeof buf, a->cents, "EUR") >= (int)sizeof buf)
        return;                              /* truncated: skip, do not print junk */
    fprintf(out, "<td class=\"money\">%s</td>\n", buf);
}
